import React, { useState, useEffect } from 'react';
import { Play, History, Terminal, CheckCircle2, ChevronDown, ChevronUp, Zap, Cpu, CloudSun, Calculator, Type } from 'lucide-react';

const API_BASE = "http://127.0.0.1:8000";

const toolIcons = {
  WeatherMockTool: <CloudSun size={16} />,
  CalculatorTool: <Calculator size={16} />,
  TextProcessorTool: <Type size={16} />,
};

const toolColors = {
  WeatherMockTool: { bg: 'bg-sky-50', text: 'text-sky-700', badge: 'bg-sky-100' },
  CalculatorTool: { bg: 'bg-amber-50', text: 'text-amber-700', badge: 'bg-amber-100' },
  TextProcessorTool: { bg: 'bg-violet-50', text: 'text-violet-700', badge: 'bg-violet-100' },
};

function App() {
  const [input, setInput] = useState('');
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [currentTask, setCurrentTask] = useState(null);
  const [expandedId, setExpandedId] = useState(null);

  useEffect(() => { fetchHistory(); }, []);

  const fetchHistory = async () => {
    try {
      const res = await fetch(`${API_BASE}/tasks`);
      const data = await res.json();
      setHistory(data);
    } catch (e) { console.error(e); }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim()) return;
    setLoading(true);
    try {
      const res = await fetch(`${API_BASE}/tasks`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ task: input })
      });
      const data = await res.json();
      setCurrentTask(data);
      setInput('');
      fetchHistory();
    } catch (e) { alert("Error connecting to backend. Make sure the server is running on port 8000."); }
    finally { setLoading(false); }
  };

  const quickExamples = [
    "Calculate 42 * 18",
    "weather in Tokyo",
    "Make this uppercase: hello world",
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-slate-100">
      <div className="h-1 bg-gradient-to-r from-blue-600 via-indigo-500 to-violet-600" />

      <div className="max-w-3xl mx-auto px-6 py-10">
        {/* Header */}
        <header className="mb-10 text-center">
          <div className="inline-flex items-center gap-2 bg-slate-900 text-white px-4 py-1.5 rounded-full text-xs font-semibold tracking-wide mb-4 shadow-lg">
            <Cpu size={14} className="text-blue-400" />
            AGENT TASK RUNNER
          </div>
          <h1 className="text-4xl font-extrabold text-slate-900 tracking-tight">
            Autonomous Tool Execution
          </h1>
          <p className="text-slate-500 mt-2 text-lg">
            Weather mock, calculator &amp; text processing — powered by an agentic pipeline.
          </p>
        </header>

        {/* Input Form */}
        <div className="bg-white rounded-2xl shadow-lg shadow-slate-200/60 border border-slate-200 p-6 mb-8">
          <div className="flex items-center gap-2 mb-4">
            <Zap size={18} className="text-blue-600" />
            <span className="font-bold text-slate-800">New Task</span>
          </div>

          <form onSubmit={handleSubmit}>
            <textarea
              rows="3"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder='e.g. Calculate 15 * 25, weather in London, uppercase: hello world'
              className="w-full p-4 text-base border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-blue-500/30 focus:border-blue-400 transition-all resize-none bg-slate-50 placeholder:text-slate-400"
            />

            <div className="flex flex-wrap gap-2 mt-3 mb-4">
              {quickExamples.map((ex, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => setInput(ex)}
                  className="text-xs px-3 py-1.5 bg-slate-100 hover:bg-blue-50 hover:text-blue-700 text-slate-600 rounded-lg transition-colors border border-transparent hover:border-blue-200"
                >
                  {ex}
                </button>
              ))}
            </div>

            <button
              disabled={loading || !input.trim()}
              className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-bold py-3.5 rounded-xl flex items-center justify-center gap-2 transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed shadow-md shadow-blue-600/20"
            >
              {loading ? (
                <span className="flex items-center gap-2">
                  <svg className="animate-spin h-5 w-5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z"/></svg>
                  Processing...
                </span>
              ) : (
                <><Play size={18} /> Execute Task</>
              )}
            </button>
          </form>
        </div>

        {/* Execution Result */}
        {currentTask && (
          <div className="mb-8 bg-slate-900 rounded-2xl overflow-hidden shadow-xl border border-slate-800">
            <div className="flex items-center gap-2 px-5 py-3 bg-slate-800/60 border-b border-slate-700/50">
              <div className="flex gap-1.5">
                <div className="w-3 h-3 rounded-full bg-red-500/80" />
                <div className="w-3 h-3 rounded-full bg-yellow-500/80" />
                <div className="w-3 h-3 rounded-full bg-green-500/80" />
              </div>
              <span className="text-xs text-slate-500 font-mono ml-2 flex items-center gap-1.5">
                <Terminal size={12} /> execution_trace.log
              </span>
            </div>

            <div className="p-5 font-mono text-sm">
              <div className="space-y-1.5 text-slate-400">
                {currentTask.steps && currentTask.steps.map((step, i) => (
                  <div key={i} className="flex gap-2">
                    <span className="text-slate-600 select-none">{String(i + 1).padStart(2, '0')}</span>
                    <span className={i === currentTask.steps.length - 1 ? 'text-green-400' : ''}>{step}</span>
                  </div>
                ))}
              </div>

              <div className="mt-5 pt-4 border-t border-slate-700/50">
                <p className="text-xs uppercase text-blue-400 font-bold tracking-widest mb-2">Output</p>
                <p className="text-xl text-white font-sans font-bold leading-relaxed">{currentTask.output_text}</p>
                <div className="mt-3">
                  <span className={`inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-md font-medium ${
                    toolColors[currentTask.tool_used]?.badge || 'bg-slate-700'
                  } ${toolColors[currentTask.tool_used]?.text || 'text-slate-300'}`}>
                    {toolIcons[currentTask.tool_used]} {currentTask.tool_used}
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* History */}
        <section>
          <div className="flex items-center gap-2 mb-5">
            <History size={20} className="text-slate-400" />
            <h2 className="font-bold text-xl text-slate-800">History</h2>
            <span className="text-xs text-slate-400 bg-slate-100 px-2 py-0.5 rounded-full ml-1">{history.length}</span>
          </div>

          {history.length === 0 && (
            <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl">
              No tasks yet. Run your first task above!
            </div>
          )}

          <div className="space-y-2.5">
            {history.map((task) => {
              const colors = toolColors[task.tool_used] || { bg: 'bg-slate-50', text: 'text-slate-600', badge: 'bg-slate-100' };
              return (
                <div
                  key={task.id}
                  className={`bg-white border rounded-xl overflow-hidden shadow-sm hover:shadow-md transition-all duration-200 ${expandedId === task.id ? 'ring-2 ring-blue-500/20' : ''}`}
                >
                  <div
                    className="p-4 flex justify-between items-center cursor-pointer select-none"
                    onClick={() => setExpandedId(expandedId === task.id ? null : task.id)}
                  >
                    <div className="flex items-center gap-3 min-w-0">
                      <div className={`p-2 rounded-lg ${colors.badge} ${colors.text} shrink-0`}>
                        {toolIcons[task.tool_used] || <CheckCircle2 size={16} />}
                      </div>
                      <div className="min-w-0">
                        <p className="font-semibold text-slate-800 truncate">{task.input_text}</p>
                        <p className="text-xs text-slate-400 mt-0.5">
                          {task.tool_used} &middot; {task.timestamp ? new Date(task.timestamp).toLocaleString() : ''}
                        </p>
                      </div>
                    </div>
                    <div className="flex items-center gap-4 shrink-0 ml-4">
                      <span className="font-bold text-slate-700 text-sm max-w-xs truncate hidden sm:block">{task.output_text}</span>
                      {expandedId === task.id ? <ChevronUp size={18} className="text-slate-400" /> : <ChevronDown size={18} className="text-slate-400" />}
                    </div>
                  </div>

                  {expandedId === task.id && (
                    <div className="bg-slate-50 p-4 border-t text-xs font-mono text-slate-600 space-y-1">
                      <p className="font-bold text-slate-400 uppercase tracking-wider mb-2" style={{fontSize:'10px'}}>Execution Trace</p>
                      {task.steps && task.steps.map((s, idx) => (
                        <p key={idx} className="text-slate-500">{s}</p>
                      ))}
                      <div className="pt-3 mt-3 border-t border-slate-200">
                        <span className="text-slate-700 font-sans font-bold text-base">{task.output_text}</span>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </section>

        <footer className="mt-12 pt-6 border-t border-slate-200 text-center text-xs text-slate-400">
          Agent Task Runner &middot; WeatherMock &middot; Calculator &middot; TextProcessor
        </footer>
      </div>
    </div>
  );
}

export default App;
